// Datos: extras para el portal Accounting Standards & Financial Reporting (ES).
// Glosario, plan contable, laboratorio de asientos, laboratorio de impactos,
// casos prácticos, banco de entrevistas y paquete de cierre mensual.

export const GLOSSARY = [
  { term: 'Devengo', definition: 'Asiento contable que reconoce ingresos devengados o gastos incurridos en el periodo actual aunque el efectivo correspondiente aún no se haya recibido ni pagado, siguiendo la base de devengo exigida por el Marco Conceptual.' },
  { term: 'Coste amortizado', definition: 'Medición de un activo o pasivo financiero en el reconocimiento inicial menos los reembolsos del principal, más o menos la amortización acumulada de cualquier descuento o prima mediante el método del tipo de interés efectivo, y ajustada por cualquier corrección de valor por pérdidas (NIIF 9).' },
  { term: 'Activo', definition: 'Recurso económico presente controlado por la entidad como resultado de sucesos pasados, con potencial para producir beneficios económicos (Marco Conceptual).' },
  { term: 'Balance (de situación)', definition: 'El estado de situación financiera que presenta los activos, pasivos y patrimonio neto de una entidad en un momento determinado, regido por los requisitos de presentación de la NIC 1.' },
  { term: 'Flujo de caja', definition: 'Las entradas y salidas de efectivo y equivalentes al efectivo durante un periodo, clasificadas en actividades de explotación, inversión y financiación según la NIC 7.' },
  { term: 'CGU', definition: 'Unidad generadora de efectivo (cash-generating unit): el grupo identificable de activos más pequeño que genera entradas de efectivo que son en buena medida independientes de las de otros activos o grupos de activos; el nivel al que se someten a la prueba de deterioro el fondo de comercio y los activos corporativos según la NIC 36.' },
  { term: 'Pasivo contingente', definition: 'Obligación posible derivada de sucesos pasados cuya existencia se confirmará solo con sucesos futuros inciertos, u obligación presente que no se reconoce porque la salida de recursos no es probable o no puede medirse con fiabilidad (NIC 37); se revela, no se reconoce.' },
  { term: 'Deteriorado crediticiamente', definition: 'Un activo financiero está deteriorado crediticiamente (Etapa 3) cuando han ocurrido uno o más sucesos con un impacto perjudicial en sus flujos de efectivo futuros estimados, como dificultades financieras significativas del prestatario o un incumplimiento contractual (NIIF 9).' },
  { term: 'Activo corriente', definition: 'Activo que se espera realizar, vender o consumir en el ciclo normal de explotación de la entidad o en los doce meses siguientes a la fecha de información (NIC 1).' },
  { term: 'Impuesto diferido', definition: 'Impuesto a pagar o recuperar en ejercicios futuros derivado de diferencias temporarias entre los importes en libros de activos y pasivos y sus bases fiscales, reconocido según la NIC 12 mediante el método del pasivo del balance.' },
  { term: 'Amortización', definition: 'La distribución sistemática del importe amortizable del inmovilizado material a lo largo de su vida útil (NIC 16); es un proceso de distribución del coste, no un ejercicio de valoración.' },
  { term: 'EBITDA', definition: 'Resultado antes de intereses, impuestos, amortización y depreciación; medida de rendimiento no GAAP utilizada para evaluar la rentabilidad operativa antes de la financiación, los impuestos y los cargos no monetarios.' },
  { term: 'ECL', definition: 'Pérdidas crediticias esperadas (expected credit losses): la media ponderada por probabilidad de las pérdidas crediticias, utilizando como ponderaciones los respectivos riesgos de impago. La NIIF 9 exige una corrección por pérdidas esperadas a 12 meses para los activos de la Etapa 1 y pérdidas esperadas durante toda la vida para los activos de las Etapas 2 y 3.' },
  { term: 'Tipo de interés efectivo', definition: 'El tipo que descuenta exactamente los cobros o pagos futuros estimados durante la vida esperada de un instrumento financiero hasta su importe en libros bruto (para activos) o su coste amortizado (para pasivos) (NIIF 9).' },
  { term: 'Patrimonio neto', definition: 'La participación residual en los activos de la entidad una vez deducidos todos sus pasivos (Marco Conceptual).' },
  { term: 'Valor razonable', definition: 'El precio que se recibiría por vender un activo o se pagaría por transferir un pasivo en una transacción ordenada entre participantes en el mercado en la fecha de medición (NIIF 13).' },
  { term: 'FVOCI', definition: 'Valor razonable con cambios en otro resultado global (fair value through other comprehensive income): categoría de medición de activos financieros en la que los cambios de valor razonable se reconocen en otro resultado global, y solo los intereses, el deterioro y las diferencias de cambio se reconocen en resultados para los instrumentos de deuda (NIIF 9).' },
  { term: 'FVTPL', definition: 'Valor razonable con cambios en resultados (fair value through profit or loss): categoría de medición en la que todos los cambios de valor razonable de un activo o pasivo financiero se reconocen en resultados (NIIF 9).' },
  { term: 'Empresa en funcionamiento', definition: 'La hipótesis de que la entidad continuará operando en un futuro previsible (al menos doce meses desde la fecha de información), que sustenta la preparación de los estados financieros sobre una base distinta de la liquidación (NIC 1).' },
  { term: 'Fondo de comercio', definition: 'El exceso de la contraprestación transferida (más cualquier participación no dominante y el valor razonable de cualquier participación previa) sobre el valor razonable de los activos netos identificables adquiridos en una combinación de negocios (NIIF 3); no se amortiza y las pérdidas por deterioro del fondo de comercio nunca se revierten.' },
  { term: 'Margen bruto', definition: 'Ingresos ordinarios menos coste de ventas, expresado como importe o como porcentaje de los ingresos ordinarios; mide la rentabilidad de producción y precios antes de los gastos operativos.' },
  { term: 'IAS', definition: 'Normas Internacionales de Contabilidad (International Accounting Standards): la serie más antigua de normas emitidas por el IASC, muchas aún vigentes (por ejemplo, la NIC 16 y la NIC 37), hoy mantenidas por el IASB junto con las NIIF.' },
  { term: 'IFRS', definition: 'Normas Internacionales de Información Financiera (International Financial Reporting Standards): el conjunto de normas contables emitidas por el IASB que regulan el reconocimiento, la medición, la presentación y la información a revelar en los estados financieros con propósito general.' },
  { term: 'Deterioro', definition: 'Pérdida reconocida cuando el importe en libros de un activo supera su importe recuperable (NIC 36); para los activos financieros, el deterioro se mide a través de las pérdidas crediticias esperadas según la NIIF 9.' },
  { term: 'Pasivo', definition: 'Obligación presente de la entidad de transferir un recurso económico como resultado de sucesos pasados (Marco Conceptual).' },
  { term: 'Importancia relativa', definition: 'La información es material si su omisión, inexactitud u ocultación pudiera razonablemente influir en las decisiones de los usuarios principales de los estados financieros (NIC 1 y Marco Conceptual).' },
  { term: 'NCI', definition: 'Participación no dominante (non-controlling interest): el patrimonio neto de una filial no atribuible, directa o indirectamente, a la dominante; se presenta por separado dentro del patrimonio neto consolidado (NIIF 10).' },
  { term: 'Valor neto realizable', definition: 'El precio de venta estimado en el curso normal del negocio menos los costes estimados para completar la producción y los costes estimados necesarios para realizar la venta (NIC 2); las existencias se miden al menor entre el coste y el valor neto realizable.' },
  { term: 'Provisión', definition: 'Pasivo de vencimiento o importe incierto, reconocido cuando existe una obligación presente derivada de un suceso pasado, es probable una salida de recursos y puede hacerse una estimación fiable (NIC 37).' },
  { term: 'Ingresos ordinarios', definition: 'Ingresos surgidos en el curso ordinario de las actividades de la entidad, reconocidos según la NIIF 15 cuando (o a medida que) la entidad satisface una obligación de desempeño transfiriendo un bien o servicio comprometido al cliente.' },
  { term: 'Activo por derecho de uso', definition: 'El activo del arrendatario que representa su derecho a usar un activo subyacente durante el plazo del arrendamiento, medido inicialmente al coste incluyendo el pasivo por arrendamiento inicial (NIIF 16) y amortizado posteriormente.' },
  { term: 'SICR', definition: 'Incremento significativo del riesgo de crédito (significant increase in credit risk): el desencadenante que traslada un instrumento financiero de la Etapa 1 (pérdidas esperadas a 12 meses) a la Etapa 2 (pérdidas esperadas durante toda la vida) según la NIIF 9, evaluado comparando el riesgo de impago a la fecha de información con el existente en el reconocimiento inicial.' },
  { term: 'Etapa 1', definition: 'Activos financieros con buen comportamiento sin incremento significativo del riesgo de crédito desde el reconocimiento inicial: se reconoce una corrección por pérdidas crediticias esperadas a 12 meses y los intereses se calculan sobre el importe en libros bruto (NIIF 9).' },
  { term: 'Etapa 2', definition: 'Activos financieros con un incremento significativo del riesgo de crédito desde el reconocimiento inicial pero aún no deteriorados crediticiamente: se reconocen pérdidas crediticias esperadas durante toda la vida mientras los intereses siguen calculándose sobre el importe en libros bruto (NIIF 9).' },
  { term: 'Etapa 3', definition: 'Activos financieros deteriorados crediticiamente: se reconocen pérdidas crediticias esperadas durante toda la vida y los ingresos por intereses se calculan sobre el importe en libros neto, es decir, tras deducir la corrección por pérdidas (NIIF 9).' },
  { term: 'Fondo de maniobra', definition: 'Activos corrientes menos pasivos corrientes; medida de la liquidez a corto plazo y del capital operativo inmovilizado en el ciclo del negocio.' },
  { term: 'Importe en libros', definition: 'El importe por el que se reconoce un activo o pasivo en el balance de situación, tras deducir la depreciación, amortización o deterioro acumulados y cualquier corrección por pérdidas.' },
  { term: 'Tipo de cambio de cierre', definition: 'El tipo de cambio al contado al final del periodo de información, utilizado según la NIC 21 para reexpresar los activos y pasivos monetarios denominados en moneda extranjera.' },
  { term: 'Control', definition: 'Un inversor controla una participada cuando tiene poder sobre ella, exposición o derechos a rendimientos variables, y capacidad para utilizar su poder e influir en esos rendimientos (NIIF 10); el control desencadena la consolidación plena.' },
  { term: 'Corte (de operaciones)', definition: 'El principio de que las operaciones se registran en el periodo contable correcto, de modo que ingresos, gastos, activos y pasivos se reconocen cuando ocurre el hecho subyacente y no cuando se mueve el efectivo.' },
  { term: 'Partida doble', definition: 'El sistema en el que toda operación se registra con débitos y créditos iguales, manteniendo equilibrada la ecuación contable (activo = pasivo + patrimonio neto) en todo momento.' },
  { term: 'Activo financiero', definition: 'Efectivo, un instrumento de patrimonio de otra entidad, o un derecho contractual a recibir efectivo u otro activo financiero (NIIF 9); su clasificación depende del modelo de negocio de la entidad y de la prueba SPPI (únicamente pagos de principal e intereses).' },
  { term: 'Moneda funcional', definition: 'La moneda del entorno económico principal en el que opera la entidad; las operaciones en moneda extranjera se miden traduciéndolas a la moneda funcional según la NIC 21.' },
  { term: 'Asiento (contable)', definition: 'El registro formal de una operación en el diario general, que especifica las cuentas cargadas y abonadas y los importes; los asientos son los bloques de construcción de la partida doble.' },
  { term: 'Pasivo por arrendamiento', definition: 'La obligación del arrendatario de realizar los pagos del arrendamiento, medida al valor actual de los pagos futuros descontados al tipo de interés implícito en el arrendamiento o, si no puede determinarse, al tipo de interés incremental del endeudamiento (NIIF 16).' },
  { term: 'Principio de correlación', definition: 'El concepto de que los gastos se reconocen en el mismo periodo que los ingresos relacionados que ayudaron a generar, para una medición fiel del rendimiento periódico.' },
  { term: 'Valor actual', definition: 'El valor actual de una suma futura de dinero o de un flujo de flujos de efectivo, descontado a un tipo apropiado para reflejar el valor temporal del dinero; la base para medir los pasivos por arrendamiento, las provisiones y el valor en uso.' },
  { term: 'Importe recuperable', definition: 'El mayor entre el valor razonable menos los costes de enajenación de un activo (o CGU) y su valor en uso; el referente con el que se compara el importe en libros en la prueba de deterioro (NIC 36).' },
  { term: 'Aplicación retroactiva', definition: 'Aplicar una nueva política contable o corregir un error de ejercicios anteriores como si siempre se hubiera aplicado, con reexpresión de la información comparativa (NIC 8).' },
  { term: 'Filial', definition: 'Entidad controlada por otra entidad (la dominante); sus estados financieros se consolidan línea a línea con los de la dominante (NIIF 10).' },
  { term: 'Balance de comprobación', definition: 'Relación de todos los saldos de las cuentas del libro mayor en un momento determinado, utilizada para verificar que el total de débitos iguala al total de créditos antes de preparar los estados financieros.' },
  { term: 'Valor en uso', definition: 'El valor actual de los flujos de efectivo futuros que se espera obtener de un activo o de una unidad generadora de efectivo; una de las dos medidas utilizadas para determinar el importe recuperable según la NIC 36.' },
];

